#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package Microsoft.CodeAnalysis.CSharp@4.7.0 #:package Microsoft.CodeAnalysis.Analyzers@3.3.4 #:package xunit@2.6.0 #:package FluentAssertions@6.12.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Text; using Microsoft.CodeAnalysis; using Microsoft.CodeAnalysis.Text; using Microsoft.CodeAnalysis.CSharp.Syntax;  // 1. 自定义属性扩展 [AttributeUsage(AttributeTargets.Class)] public class MultiLanguageAttribute : Attribute {     public string[] SupportedLanguages { get; }      public MultiLanguageAttribute(params string[] languages)     {         SupportedLanguages = languages;     } }  [Generator] public class CompleteGenerator : IIncrementalGenerator {     public void Initialize(IncrementalGeneratorInitializationContext context)     {         var dtoClasses = context.SyntaxProvider             .CreateSyntaxProvider(                 predicate: (node, _) => node is ClassDeclarationSyntax cds &&                      cds.AttributeLists.Any(al => al.Attributes.Any(a =>                          a.Name.ToString() == "MultiLanguage" ||                          a.Name.ToString() == "MultiLanguageAttribute")),                 transform: (ctx, _) => GetDtoInfo(ctx))             .Where(info => info != null)             .Collect();                  context.RegisterSourceOutput(dtoClasses, (ctx, infos) =>          {             foreach (var info in infos)             {                 // 生成多语言资源文件                 foreach (var lang in info.SupportedLanguages)                 {                     var resourceSource = GenerateResourceFile(info, lang);                     ctx.AddSource($"{info.Name}.{lang}.resx.g.cs", SourceText.From(resourceSource, Encoding.UTF8));                 }                                  // 生成单元测试                 var testSource = GenerateTestClass(info);                 ctx.AddSource($"{info.Name}Tests.g.cs", SourceText.From(testSource, Encoding.UTF8));             }         });     }      private DtoInfo GetDtoInfo(GeneratorSyntaxContext context)     {         var model = context.SemanticModel.GetDeclaredSymbol(context.Node);         if (model == null) return null;          var attr = model.GetAttributes()             .FirstOrDefault(a => a.AttributeClass?.Name == "MultiLanguageAttribute");                  return new DtoInfo         {             Name = model.Name,             Namespace = model.ContainingNamespace.ToDisplayString(),             SupportedLanguages = attr?.ConstructorArguments[0].Values.Select(v => v.Value?.ToString()).ToArray() ?? Array.Empty<string>(),             Properties = model.GetMembers()                 .OfType<IPropertySymbol>()                 .Select(p => new PropertyInfo                 {                     Name = p.Name,                     Type = p.Type.ToDisplayString(),                     IsNullable = p.NullableAnnotation == NullableAnnotation.Annotated                 })                 .ToList()         };     }      // 2. 生成单元测试     private string GenerateTestClass(DtoInfo info)     {         var sb = new StringBuilder();         sb.AppendLine("// <auto-generated/>");         sb.AppendLine("using Xunit;");         sb.AppendLine("using FluentAssertions;");         sb.AppendLine();         sb.AppendLine($"namespace {info.Namespace}.Tests");         sb.AppendLine("{");         sb.AppendLine($"    public class {info.Name}Tests");         sb.AppendLine("    {");         sb.AppendLine($"        [Fact]");         sb.AppendLine($"        public void Should_Have_Correct_Properties()");         sb.AppendLine("        {");         sb.AppendLine($"            var dto = new {info.Name}Dto();");                  foreach (var prop in info.Properties)         {             sb.AppendLine($"            dto.{prop.Name}.Should().Be{(prop.IsNullable ? "Null" : "Default")}();");         }                  sb.AppendLine("        }");         sb.AppendLine("    }");         sb.AppendLine("}");         return sb.ToString();     }      // 3. 多语言支持     private string GenerateResourceFile(DtoInfo info, string language)     {         var sb = new StringBuilder();         sb.AppendLine("// <auto-generated/>");         sb.AppendLine($"namespace {info.Namespace}.Resources");         sb.AppendLine("{");         sb.AppendLine($"    public static class {info.Name}Resources_{language}");         sb.AppendLine("    {");                  foreach (var prop in info.Properties)         {             sb.AppendLine($"        public static string {prop.Name} => \"{prop.Name}_{language}\";");         }                  sb.AppendLine("    }");         sb.AppendLine("}");         return sb.ToString();     } }  public class DtoInfo {     public string Name { get; set; }     public string Namespace { get; set; }     public string[] SupportedLanguages { get; set; }     public List<PropertyInfo> Properties { get; set; } }  public class PropertyInfo {     public string Name { get; set; }     public string Type { get; set; }     public bool IsNullable { get; set; } }
